const output = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const eventId = body.event_id ?? `demo-${Date.now()}`;
  const name = String(body.name ?? '').trim();
  const email = String(body.email ?? '').trim().toLowerCase();
  const company = String(body.company ?? '').trim();
  const errors = [];
  if (!name) errors.push('name is required');
  if (!email || !email.includes('@')) errors.push('valid email is required');
  if (errors.length) {
    output.push({ json: { ok: false, event_id: eventId, errors } });
    continue;
  }
  output.push({ json: {
    ok: true, event_id: eventId,
    lead: { name, email, company, interest: body.interest ?? null, source: body.source ?? 'unknown' },
    next_action: 'Create CRM record and schedule follow-up within 24 hours',
    processed_at: new Date().toISOString()
  }});
}
return output;
